RList* get_global_entries_from_section(RBinWasmObj *bin, RBinWasmSection *sec) {
    RList *global_entries = r_list_new();
    if (!global_entries) {
        return NULL;
    }

    ut32 buffer_len = sec->size;
    ut32 offset = 0;

    while (offset < buffer_len) {
        RBinWasmGlobalEntry *entry = r_bin_wasm_global_entry_new();
        if (!entry) {
            r_list_free(global_entries);
            return global_entries;
        }

        // Extract content type and mutability from the buffer
        if (offset + 1 > buffer_len) {
            r_bin_wasm_global_entry_free(entry);
            r_list_free(global_entries);
            return global_entries;
        }

        entry->type = bin->buffer[offset];
        entry->is_mutable = bin->buffer[offset + 1];
        offset += 2;

        // Append to list
        r_list_append(global_entries, entry);
    }

    return global_entries;
}

RList* get_global_entries(RBinWasmObj *bin, RBinWasmSection *sec) {
    RList *list = r_list_new();
    if (!list) {
        return NULL;
    }

    const ut8 *buf = sec->buf;
    size_t len = sec->size;
    size_t i = 0;

    while (i < len) {
        RBinWasmGlobalEntry *entry = calloc(1, sizeof(RBinWasmGlobalEntry));
        if (!entry) {
            r_list_free(list);
            return list;
        }

        // Parse content type and mutability
        if (i + 1 >= len) {
            free(entry);
            r_list_free(list);
            return list;
        }

        entry->content_type = buf[i];
        entry->mutable = buf[i + 1];
        i += 2;

        if (!r_list_append(list, entry)) {
            free(entry);
            r_list_free(list);
            return list;
        }
    }

    return list;
}

RList* r_bin_wasm_get_global_entries(RBinWasmObj *bin, RBinWasmSection *sec) {
    RList *globals = r_list_new();
    if (!globals) {
        return NULL;
    }

    ut8 *buf = sec->data;
    int len = sec->size;
    int i = 0;

    while (i < len) {
        RBinWasmGlobalEntry *entry = R_NEW0(RBinWasmGlobalEntry);
        if (!entry) {
            r_list_free(globals);
            return globals;
        }

        if (i + 1 > len) {
            free(entry);
            r_list_free(globals);
            return NULL;
        }

        entry->content = buf[i];
        i += 1;

        if (i + 1 > len) {
            free(entry);
            r_list_free(globals);
            return NULL;
        }

        entry->mutability = (buf[i] == 0x01);
        i += 1;

        if (!r_list_append(globals, entry)) {
            free(entry);
            r_list_free(globals);
            return globals;
        }
    }

    return globals;
}

