RList* get_global_entries_from_wasm_section(RBinWasmObj *bin, RBinWasmSection *sec) {
    RList *global_entries = r_list_new();
    if (!global_entries) {
        return NULL;
    }

    size_t offset = 0;
    while (offset < sec->size) {
        RBinWasmGlobalEntry *entry = r_bin_wasm_global_entry_new();
        if (!entry) {
            break;
        }

        bool success = r_bin_wasm_parse_global_entry(bin, sec->data + offset, sec->size - offset, entry);
        if (!success) {
            r_bin_wasm_global_entry_free(entry);
            break;
        }

        offset += entry->size;
        r_list_append(global_entries, entry);
    }

    if (global_entries->length == 0) {
        r_list_free(global_entries);
        return NULL;
    }

    return global_entries;
}
